const state={inventory:[],customers:[],routes:[],selectedRoute:'',orders:[],distributionOrders:[],topups:[],templates:[],cart:new Map(),customProducts:new Map(),invoiceLines:[],currentInvoice:null,editingCustomerId:null,editingInvoiceId:null,invoiceOrderId:null};
const $=selector=>document.querySelector(selector);
const money=paise=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:2}).format((Number(paise)||0)/100);
const escapeHtml=value=>{const node=document.createElement('span');node.textContent=String(value??'');return node.innerHTML};
const displayDate=value=>{if(!value)return'—';const raw=String(value),normalized=raw.length===10?raw+'T00:00:00':raw.includes('T')?raw:raw.replace(' ','T')+'Z',date=new Date(normalized);return Number.isNaN(date.getTime())?'—':date.toLocaleDateString('en-IN')};
const templateNames={amul_catalogue:'Catalogue invitation',payment_remainder:'Payment reminder',order_delivery_update:'Order & delivery update'};
const templateFieldNames={payment_remainder:['Customer name','Invoice number','Outstanding amount (numbers only)','Payment due date'],order_delivery_update:['Customer name','Order number','Current delivery status','Expected delivery date']};
const orderStatusNames={RECEIVED:'Received',CONFIRMED:'Confirmed',PICKING:'Picking',PACKING:'Picking',PACKED:'In crate',INVOICE_QUEUED:'Invoice queued',INVOICE_FAILED:'Invoice needs attention',INVOICED:'Invoiced',OUT_FOR_DELIVERY:'Out for delivery',DELIVERED:'Delivered',CANCELLED:'Cancelled'};
const orderStatusText=value=>orderStatusNames[String(value||'').toUpperCase()]||String(value||'Update').replaceAll('_',' ').toLowerCase();
const orderUpdateReady=value=>['PACKING','PACKED','OUT_FOR_DELIVERY','DELIVERED'].includes(String(value||'').toUpperCase());

async function api(path,options={}){const response=await fetch(path,{...options,headers:{...(options.body?{'content-type':'application/json'}:{}),...(options.headers||{})}});const raw=await response.text();let body;try{body=JSON.parse(raw)}catch{body={error:raw}}if(!response.ok)throw new Error(body.error||`HTTP ${response.status}`);return body}
function toast(message){const box=$('#toast');box.textContent=message;box.classList.add('show');setTimeout(()=>box.classList.remove('show'),2600)}
function metric(label,value,note=''){return `<article class="metric"><small>${escapeHtml(label)}</small><strong>${escapeHtml(value)}</strong>${note?`<span>${escapeHtml(note)}</span>`:''}</article>`}

async function loadDashboard(){const data=await api('/api/dashboard');$('#metrics').innerHTML=[metric('Available products',data.inventory?.products||0,`${data.inventory?.out_of_stock||0} out of stock`),metric('Open online orders',data.orders?.open_orders||0,money(data.orders?.today_value_paise||0)+' today'),metric('Customers',data.customers?.customers||0),metric('Receivables',money(data.accounts?.receivable_paise||0),`${money(data.accounts?.overdue_paise||0)} overdue`),metric('Sales this month',money(data.accounts?.month_sales_paise||0)),metric('Reserved stock',data.inventory?.reserved_units||0)].join('');const entries=data.sync||[];$('#sync-list').innerHTML=entries.map(row=>{let value={};try{value=JSON.parse(row.value)}catch{}return `<div><strong>${escapeHtml(row.key.replace('business:',''))}</strong><span>${escapeHtml(value.record_count??value.product_count??0)} records · ${escapeHtml(displayDate(value.captured_at||row.updated_at))}</span></div>`}).join('')||'<p class="empty">Waiting for the first Amul PC sync.</p>';const latest=entries.find(row=>row.key==='current_snapshot');if(latest){let value={};try{value=JSON.parse(latest.value)}catch{}$('#sync').textContent=`Synced ${new Date(value.captured_at||latest.updated_at).toLocaleString('en-IN')}`}else $('#sync').textContent='Waiting for PC sync'}

function healthMetric(label,value,note,tone=''){return `<article class="health-metric ${tone}"><span>${escapeHtml(label)}</span><strong>${escapeHtml(value)}</strong><small>${escapeHtml(note)}</small></article>`}
function healthSection(title,rows,render){return `<details><summary><span>${escapeHtml(title)}</span><b>${rows.length}</b></summary><div>${rows.length?rows.map(render).join(''):'<p class="empty">No records need review.</p>'}</div></details>`}
async function loadReconciliation(){const data=await api('/api/reconciliation'),summary=data.summary||{},reviewTotal=Number(summary.duplicate_sku_groups||0)+Number(summary.stock_differences||0)+Number(summary.invoices_missing_lines||0)+Number(summary.duplicate_phone_groups||0);$('#health-status').className=`health-badge ${reviewTotal?'warning':''}`;$('#health-status').innerHTML=`<i></i>${reviewTotal?' Review queue ready':' Reconciled'}`;$('#health-summary').innerHTML=[healthMetric('Duplicate SKU groups',summary.duplicate_sku_groups||0,`${summary.duplicate_product_records||0} product records`,summary.duplicate_sku_groups?'warning':''),healthMetric('Source stock differences',summary.stock_differences||0,`${summary.stock_units_difference||0} total units`,summary.stock_differences?'info':''),healthMetric('Invoice details to normalize',summary.invoices_missing_lines||0,'Archive remains available',summary.invoices_missing_lines?'info':''),healthMetric('Duplicate phone groups',summary.duplicate_phone_groups||0,'Customer review',summary.duplicate_phone_groups?'warning':''),healthMetric('Protected archive',summary.archived_rows||0,`${summary.archived_tables||0} source tables`)].join('');$('#health-details').innerHTML=[healthSection('Duplicate product codes',data.duplicate_skus||[],row=>`<p><strong>${escapeHtml(row.sku)}</strong><span>${row.records} records · ${escapeHtml(row.sources||'')}</span><small>${escapeHtml(row.product_names||'')}</small></p>`),healthSection('Cloud stock versus latest source observation',data.stock_differences||[],row=>`<p><strong>${escapeHtml(row.product_name)}</strong><span>Cloud ${row.stock_qty} · Source ${row.source_stock_qty} ${escapeHtml(row.unit)}</span><small>${escapeHtml(row.sku||row.product_id)} · Difference ${row.difference}</small></p>`),healthSection('Invoices using archived detail',data.invoices_missing_lines||[],row=>`<p><strong>${escapeHtml(row.invoice_number)}</strong><span>${escapeHtml(row.customer_name)} · ${money(row.total_paise)}</span><small>${escapeHtml(row.source)} · ${displayDate(row.invoice_date)}</small></p>`),healthSection('Customers sharing a phone number',data.duplicate_phones||[],row=>`<p><strong>${escapeHtml(row.phone)}</strong><span>${row.records} customer records</span><small>${escapeHtml(row.customer_names||'')}</small></p>`)].join('')}

function productCard(item){const quantity=state.cart.get(item.product_id)||0,out=!!item.manual_out_of_stock;return `<article class="product-card ${out?'stock-locked':''}"><div><span class="category-tag">${escapeHtml(item.category||'Other')}</span><h3>${escapeHtml(item.product_name)}</h3><p class="meta">${escapeHtml(item.sku||item.product_id)}</p><p><strong>${money(item.selling_price_paise)}</strong> <span class="strike">${money(item.mrp_paise)}</span></p><p class="stock">${out?'Hidden from customers':`${item.available_qty} ${escapeHtml(item.unit)} available`}</p>${item.stock_note?`<p class="meta">${escapeHtml(item.stock_note)}</p>`:''}</div><div class="stepper" data-product="${escapeHtml(item.product_id)}"><button type="button" data-minus aria-label="Reduce quantity">−</button><output>${quantity}</output><button type="button" data-plus aria-label="Increase quantity" ${out||item.available_qty<=quantity?'disabled':''}>+</button></div><details class="stock-menu"><summary>Manage stock</summary><div class="stock-actions"><button type="button" class="secondary" data-set-stock="${escapeHtml(item.product_id)}">Set quantity</button><button type="button" class="secondary" data-stock-toggle="${escapeHtml(item.product_id)}" data-next="${out?'available':'out'}">${out?'Show in catalogue':'Mark unavailable'}</button><button type="button" class="secondary" data-topup="${escapeHtml(item.product_id)}">Purchase top-up</button></div></details></article>`}
function renderInventory(){const query=$('#search').value.trim().toLowerCase(),selected=$('#category').value;const rows=state.inventory.filter(item=>(!selected||item.category===selected)&&(!query||`${item.product_name} ${item.sku}`.toLowerCase().includes(query)));$('#inventory-list').innerHTML=rows.map(productCard).join('')||'<p class="empty">No matching products.</p>'}
async function loadInventory(){const [data,topups]=await Promise.all([api('/api/inventory?limit=200'),api('/api/purchase-topups')]);state.inventory=data.items;state.topups=topups.topups||[];const selected=$('#category').value;const categories=[...new Set(state.inventory.map(item=>item.category||'Other'))].sort();$('#category').innerHTML='<option value="">All categories</option>'+categories.map(name=>`<option ${name===selected?'selected':''}>${escapeHtml(name)}</option>`).join('');renderInventory();renderCart();renderTopups()}
function renderTopups(){$('#topups-list').innerHTML=state.topups.map(row=>`<article class="card"><div><div class="eyebrow">${escapeHtml(row.reference||'LATEST TOP-UP')}</div><h3>${escapeHtml(row.product_name)}</h3><p class="meta">${escapeHtml(row.sku||row.product_id)} · ${displayDate(row.created_at)}</p>${row.note?`<p>${escapeHtml(row.note)}</p>`:''}</div><div><span class="status">Active</span><strong>${row.requested_qty} ${escapeHtml(row.unit)}</strong></div></article>`).join('')||'<p class="empty">No active top-ups.</p>'}
function findProduct(productId){return state.inventory.find(item=>item.product_id===productId)||state.customProducts.get(productId)}
function changeQuantity(productId,delta){const product=findProduct(productId);if(!product)return;const current=state.cart.get(productId)||0;const next=Math.max(0,Math.min(Number(product.available_qty||1000),current+delta));if(next)state.cart.set(productId,next);else{state.cart.delete(productId);if(product.is_custom)state.customProducts.delete(productId)}renderInventory();renderCart()}
function renderCart(){const lines=[...state.cart].map(([id,quantity])=>({product:findProduct(id),quantity})).filter(row=>row.product);const totalQty=lines.reduce((sum,row)=>sum+row.quantity,0);const total=lines.reduce((sum,row)=>sum+row.quantity*Number(row.product.selling_price_paise||0),0);$('#cart-count').textContent=totalQty;$('#cart-lines').innerHTML=lines.map(({product,quantity})=>`<div><span>${escapeHtml(product.product_name)}${product.is_custom?'<small class="custom-label">Custom</small>':''}<br><small class="meta">${money(product.selling_price_paise)} / ${escapeHtml(product.unit)}</small></span><span class="stepper" data-product="${escapeHtml(product.product_id)}"><button type="button" data-minus>−</button><output>${quantity}</output><button type="button" data-plus>+</button></span></div>`).join('')||'<p class="empty">Add products from the catalogue or create a custom product below.</p>';$('#cart-total').textContent=lines.length?`${lines.length} products · ${totalQty} units · ${money(total)}`:'';$('#submit-order').disabled=!lines.length}

function orderActions(order){if(!['NEW','SYNCED'].includes(order.status))return'';const status=order.workflow_status||'RECEIVED',ready=order.lines?.length&&order.lines.every(line=>Number(line.picked_qty)===Number(line.quantity));return `<div class="actions">${status==='RECEIVED'?`<button data-order-action="confirm" data-id="${order.id}">Start picking</button>`:''}${ready&&['CONFIRMED','PICKING','PACKING','PACKED','INVOICE_FAILED'].includes(status)?`<button data-checkout-order="${order.id}">Process &amp; checkout</button>`:''}${status==='INVOICED'?`<button data-order-action="dispatch" data-id="${order.id}">Dispatch &amp; notify</button>`:''}${status==='OUT_FOR_DELIVERY'?`<button data-order-action="deliver" data-id="${order.id}">Delivered &amp; notify</button>`:''}${!['INVOICED','OUT_FOR_DELIVERY','DELIVERED'].includes(status)?`<button class="danger" data-order-action="cancel" data-id="${order.id}">Cancel</button>`:''}</div>`}
function orderLineUnits(line){const unit=String(line.requested_unit||line.unit||'PC').toUpperCase().replace('PCS','PC').replace('BX','BOX'),factor=unit==='BOX'?Number(line.units_per_box||1):1,quantity=Number(line.requested_quantity??Number(line.quantity||0)/factor),picked=Number(line.picked_qty||0)/factor,crated=Number(line.crated_qty||0)/factor;return{unit,factor,quantity,picked,crated}}
function orderTaxNote(order,line){if(!Number(line.gst_bps))return'';return Number(order.tax_paise)>0?' incl. 5% GST':' · GST added at invoice'}
function pickLines(order){const enabled=['CONFIRMED','PICKING','PACKING'].includes(order.workflow_status);return `<div class="pick-list">${order.lines.map(line=>{const display=orderLineUnits(line);return `<div class="pick-line"><div><strong>${escapeHtml(line.product_name)}</strong><small>Ordered ${display.quantity} ${escapeHtml(display.unit)} · ${money(line.total_paise||Number(line.quantity)*Number(line.price_paise||0))}${orderTaxNote(order,line)}${line.crated_qty?` · In crate ${display.crated} ${escapeHtml(display.unit)}`:''}</small></div>${enabled?`<div class="stepper" data-pick-order="${order.id}" data-pick-line="${line.line_no}" data-picked="${line.picked_qty||0}" data-ordered="${line.quantity}" data-pick-step="${display.factor}"><button type="button" data-pick-minus ${Number(line.picked_qty)<=0?'disabled':''}>−</button><output>${display.picked}</output><button type="button" data-pick-plus ${Number(line.picked_qty)>=Number(line.quantity)?'disabled':''}>+</button></div>`:`<strong>${display.picked} / ${display.quantity} ${escapeHtml(display.unit)}</strong>`}</div>`}).join('')}</div>`}
function crateControl(order){const complete=order.lines.length&&order.lines.every(line=>Number(line.picked_qty)===Number(line.quantity));if(!['CONFIRMED','PICKING','PACKING'].includes(order.workflow_status)||!complete)return'';return `<form class="crate-form" data-crate-order="${order.id}"><input name="crate_code" maxlength="40" placeholder="Crate number" required><button>Add to crate</button></form>`}
function orderMatches(order,query){if(!query)return true;return [order.order_number,order.customer_name,order.phone,order.route_name,order.status,order.workflow_status,...(order.lines||[]).flatMap(line=>[line.product_name,line.product_id])].join(' ').toLowerCase().includes(query)}
function orderEstimateSummary(order){const subtotal=Number(order.subtotal_paise||order.total_paise||0),tax=Number(order.tax_paise||0);if(tax>0)return `<p class="estimate-summary"><span>Estimated invoice</span><strong>${money(subtotal)} + ${money(tax)} GST = ${money(order.total_paise)}</strong></p>`;if(Number(order.gst_bps)>0)return `<p class="estimate-summary"><span>Retailer estimate before GST</span><strong>${money(subtotal)} · GST added at invoice</strong></p>`;return `<p class="estimate-summary"><span>Order estimate</span><strong>${money(order.total_paise||subtotal)}</strong></p>`}
function renderOrders(){const query=$('#order-search').value.trim().toLowerCase(),online=state.orders.filter(order=>orderMatches(order,query)),local=state.distributionOrders.filter(order=>orderMatches(order,query));$('#orders-list').innerHTML=online.map(o=>`<article class="card order-card"><div class="order-main"><div class="eyebrow">${escapeHtml(o.order_number||'ONLINE ORDER')}</div><h3>${escapeHtml(o.customer_name)}</h3><p class="meta">${displayDate(o.created_at)} · ${escapeHtml(o.phone||'No phone')} · Expected ${displayDate(o.delivery_date)}${o.route_name?' · '+escapeHtml(o.route_name):''}</p>${o.address?`<p>${escapeHtml(o.address)}</p>`:''}${o.location_url?`<p><a href="${escapeHtml(o.location_url)}" target="_blank" rel="noreferrer">Open delivery location</a></p>`:''}${pickLines(o)}${crateControl(o)}${orderEstimateSummary(o)}${o.crate_code?`<p class="meta">Crate <strong>${escapeHtml(o.crate_code)}</strong></p>`:''}${o.invoice_number?`<p class="meta">Invoice <strong>${escapeHtml(o.invoice_number)}</strong></p>`:''}</div><div><span class="status">${escapeHtml(orderStatusText(o.workflow_status||o.status))}</span>${orderActions(o)}</div></article>`).join('')||`<p class="empty">${query?'No matching online orders.':'No online orders yet.'}</p>`;$('#distribution-orders-list').innerHTML=local.map(o=>`<article class="card"><div><div class="eyebrow">${escapeHtml(o.order_number)}</div><h3>${escapeHtml(o.customer_name)}</h3><p class="meta">${displayDate(o.order_date)} · Delivery ${displayDate(o.delivery_date)} ${o.route_name?'· '+escapeHtml(o.route_name):''}</p><p>${(o.lines||[]).map(line=>`${escapeHtml(line.product_name)} × ${line.quantity}`).join('<br>')}</p></div><div><span class="status muted">${escapeHtml(orderStatusText(o.status))}</span><strong>${money(o.total_paise)}</strong></div></article>`).join('')||`<p class="empty">${query?'No matching synced orders.':'No legacy local orders.'}</p>`}
async function loadOrders(){const [online,local]=await Promise.all([api('/api/orders'),api('/api/distribution/orders?limit=100')]);state.orders=online.orders;state.distributionOrders=local.orders;renderOrders()}

function customerCard(c){const phone=c.whatsapp_number||c.mobile||'';return `<article class="card"><div><div class="eyebrow">${escapeHtml(c.code||c.source)}</div><h3>${escapeHtml(c.name)}</h3><p class="meta">${escapeHtml(phone||'No number')}</p>${c.gstin?`<p class="meta">GSTIN ${escapeHtml(c.gstin)}</p>`:''}<p class="meta">${escapeHtml(c.address||'')}</p>${c.location_url?`<a href="${escapeHtml(c.location_url)}" target="_blank" rel="noreferrer">Delivery location</a>`:''}</div><div class="account"><small>Balance</small><strong class="${c.balance_paise>0?'due':''}">${money(c.balance_paise)}</strong><div class="invoice-actions"><button type="button" data-customer-invoice="${escapeHtml(c.id)}">Create invoice</button><button type="button" class="secondary" data-edit-customer="${escapeHtml(c.id)}">Edit</button><button type="button" class="danger" data-delete-customer="${escapeHtml(c.id)}" data-delete-customer-name="${escapeHtml(c.name)}">Delete</button>${phone?`<button type="button" class="secondary" data-chat-phone="${escapeHtml(phone)}">View chat</button><button type="button" class="secondary" data-invite-phone="${escapeHtml(phone)}" data-invite-name="${escapeHtml(c.name)}">Message anytime</button>`:''}</div>${phone?`<a href="https://wa.me/${encodeURIComponent(phone)}" target="_blank" rel="noreferrer">Open WhatsApp</a>`:''}</div></article>`}
function customerRouteOptions(selected=''){const names=state.routes.map(route=>route.name).filter(name=>name!=='Unassigned route');if(selected&&selected!=='Unassigned route'&&!names.includes(selected))names.push(selected);return '<option value="">Unassigned route</option>'+names.sort((a,b)=>a.localeCompare(b)).map(name=>`<option value="${escapeHtml(name)}" ${name===selected?'selected':''}>${escapeHtml(name)}</option>`).join('')}
function renderCustomerRoutes(){const picker=$('#customer-routes');picker.innerHTML=state.routes.map(route=>`<button type="button" class="route-choice ${state.selectedRoute===route.name?'active':''}" data-customer-route="${escapeHtml(route.name)}"><strong>${escapeHtml(route.name)}</strong><span>${Number(route.customer_count||0)} customer${Number(route.customer_count||0)===1?'':'s'}</span></button>`).join('')||'<p class="empty">No routes yet. Use Edit routes to add one.</p>';const term=$('#customer-search').value.trim().toLocaleLowerCase(),rows=state.selectedRoute?state.customers.filter(customer=>(customer.route_name||'Unassigned route')===state.selectedRoute&&(!term||[customer.name,customer.code,customer.mobile,customer.whatsapp_number,customer.gstin,customer.city].some(value=>String(value||'').toLocaleLowerCase().includes(term)))):[];$('#customer-route-title').textContent=state.selectedRoute||'Select a route';$('#customer-route-count').textContent=state.selectedRoute?`${rows.length} visible`:'';$('#customers-list').innerHTML=state.selectedRoute?(rows.map(customerCard).join('')||'<p class="empty">No matching customers in this route.</p>'):'<p class="empty">Select a route above to view and manage its customers.</p>'}
function renderRouteManager(){$('#route-manager-list').innerHTML=state.routes.filter(route=>route.name!=='Unassigned route').map(route=>`<div class="route-manager-row"><input value="${escapeHtml(route.name)}" maxlength="150" aria-label="Route name"><span>${Number(route.customer_count||0)} customers</span><button type="button" data-save-route="${escapeHtml(route.name)}">Save</button></div>`).join('')||'<p class="empty">No named routes yet.</p>'}
async function loadCustomers(){const [data,routeData]=await Promise.all([api('/api/customers?limit=500'),api('/api/routes')]);state.customers=Array.isArray(data.customers)?data.customers:[];state.routes=Array.isArray(routeData.routes)?routeData.routes:[];if(state.selectedRoute&&!state.routes.some(route=>route.name===state.selectedRoute))state.selectedRoute='';renderCustomerRoutes();const orderCurrent=$('#order-customer').value,invoiceCurrent=$('#invoice-customer').value,options=state.customers.map(c=>`<option value="${escapeHtml(c.id)}">${escapeHtml(c.name)}${c.route_name?' — '+escapeHtml(c.route_name):''}</option>`).join('');$('#order-customer').innerHTML='<option value="">Walk-in / new customer</option>'+state.customers.filter(c=>c.source!=='WHATSAPP').map(c=>`<option value="${escapeHtml(c.id)}">${escapeHtml(c.name)}${c.route_name?' — '+escapeHtml(c.route_name):''}</option>`).join('');$('#invoice-customer').innerHTML='<option value="">Select customer</option>'+options;$('#order-customer').value=state.customers.some(c=>c.id===orderCurrent)?orderCurrent:'';$('#invoice-customer').value=state.customers.some(c=>c.id===invoiceCurrent)?invoiceCurrent:'';$('#customer-route').innerHTML=customerRouteOptions($('#customer-route').value)}

async function loadAccounts(){const query=encodeURIComponent($('#account-search').value);const [invoiceData,paymentData]=await Promise.all([api('/api/invoices?limit=100&q='+query),api('/api/payments?limit=100&q='+query)]);$('#invoices-list').innerHTML=invoiceData.invoices.map(i=>{const online=i.source_device==='cloudflare-admin',editable=i.status!=='VOID';return `<article class="card"><div><div class="eyebrow">${escapeHtml(i.invoice_number)} · ${escapeHtml(online?'ONLINE':i.source)}${i.order_id?' · ORDER CHECKOUT':''}</div><h3>${escapeHtml(i.customer_name)}</h3><p class="meta">${displayDate(i.invoice_date)} · Due ${displayDate(i.due_date)} ${i.route_name?'· '+escapeHtml(i.route_name):''}</p></div><div class="account"><span class="status ${i.outstanding_paise&&i.status!=='VOID'?'warning':''}">${escapeHtml(i.status==='VOID'?'VOID':i.payment_status)}</span><strong>${money(i.total_paise)}</strong><small>${money(i.outstanding_paise)} due</small><div class="invoice-actions"><button type="button" class="secondary" data-view-invoice="${escapeHtml(i.id)}">View / print</button>${editable?`<button type="button" class="secondary" data-edit-invoice="${escapeHtml(i.id)}">Edit</button>`:''}<button type="button" class="danger" data-delete-invoice="${escapeHtml(i.id)}" data-delete-invoice-source="${online?'online':'synced'}" data-delete-invoice-paid="${Number(i.paid_paise||0)}" data-delete-invoice-order="${i.order_id?'yes':'no'}">${online?'Delete':'Delete from online'}</button>${i.outstanding_paise&&i.mobile&&i.status!=='VOID'?`<button type="button" data-payment-phone="${escapeHtml(i.mobile)}" data-payment-name="${escapeHtml(i.customer_name)}" data-payment-invoice="${escapeHtml(i.invoice_number)}" data-payment-amount="${escapeHtml((Number(i.outstanding_paise)/100).toFixed(2))}" data-payment-due="${escapeHtml(i.due_date||'Please pay at the earliest')}">Send reminder</button>`:''}</div></div></article>`}).join('')||'<p class="empty">No invoices found.</p>';$('#payments-list').innerHTML=paymentData.payments.map(p=>`<article class="card"><div><div class="eyebrow">${escapeHtml(p.receipt_number||p.source)}</div><h3>${escapeHtml(p.customer_name||'Unassigned')}</h3><p class="meta">${displayDate(p.payment_date)} · ${escapeHtml(p.method||p.direction)} ${p.reference_number?'· '+escapeHtml(p.reference_number):''}</p></div><strong>${money(p.amount_paise)}</strong></article>`).join('')||'<p class="empty">No payments found.</p>'}

const businessToday=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Kolkata',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
function datePlus(date,days){const value=new Date(`${date}T12:00:00`);value.setDate(value.getDate()+Number(days||0));return value.toISOString().slice(0,10)}
function invoiceTotals(){const values=state.invoiceLines.reduce((sum,line)=>{const subtotal=Math.round(Number(line.quantity)*Number(line.unit_price_paise)),tax=Math.round(subtotal*Number(line.gst_bps)/10000);sum.subtotal+=subtotal;sum.tax+=tax;return sum},{subtotal:0,tax:0}),discount=Math.round(Number($('#invoice-discount').value||0)*100);return{...values,discount,total:Math.max(0,values.subtotal+values.tax-discount)}}
function renderInvoiceTotals(){const total=invoiceTotals();$('#invoice-totals').innerHTML=`<div><span>Subtotal</span><strong>${money(total.subtotal)}</strong></div><div><span>GST</span><strong>${money(total.tax)}</strong></div><div><span>Discount</span><strong>− ${money(total.discount)}</strong></div><div class="grand-total"><span>Total</span><strong>${money(total.total)}</strong></div>`;$('#post-invoice').disabled=!state.invoiceLines.length||!$('#invoice-customer').value}
function renderInvoicePicker(){if(state.invoiceOrderId){$('#invoice-product-results').innerHTML='<p class="empty">This checkout uses every item picked for the selected order.</p>';return}const query=$('#invoice-product-search').value.trim().toLowerCase(),selected=new Set(state.invoiceLines.map(line=>line.product_id));const rows=state.inventory.filter(item=>!selected.has(item.product_id)&&!item.manual_out_of_stock&&Number(item.available_qty)>0&&(!query||`${item.product_name} ${item.sku}`.toLowerCase().includes(query))).slice(0,30);$('#invoice-product-results').innerHTML=rows.map(item=>`<button type="button" class="picker-result" data-invoice-product="${escapeHtml(item.product_id)}"><span><strong>${escapeHtml(item.product_name)}</strong><small>${escapeHtml(item.sku||item.category)} · ${item.available_qty} ${escapeHtml(item.unit)}</small></span><b>${money(item.selling_price_paise)}</b></button>`).join('')||'<p class="empty">No available matching products.</p>'}
function renderInvoiceLines(){const locked=!!state.invoiceOrderId,container=$('#invoice-lines');container.innerHTML=state.invoiceLines.map((line,index)=>`<div class="invoice-line ${locked?'locked-line':''}" data-invoice-line="${index}"><strong>${escapeHtml(line.product_name)}<small class="meta"><br>${escapeHtml(line.sku||line.product_id)} · ${line.available_qty} ${escapeHtml(line.unit)} available</small></strong><label>Qty<input data-line-field="quantity" type="number" min="0.01" max="${line.available_qty}" step="0.01" value="${line.quantity}" ${locked?'readonly':''}></label><label>Rate ₹<input data-line-field="price" type="number" min="0" step="0.01" value="${(line.unit_price_paise/100).toFixed(2)}" ${locked?'readonly':''}></label><label>GST %<input data-line-field="gst" type="number" min="0" max="50" step="0.01" value="${(line.gst_bps/100).toFixed(2)}" ${locked?'readonly':''}></label><span class="invoice-line-total">${money(Math.round(line.quantity*line.unit_price_paise*(1+line.gst_bps/10000)))}</span>${locked?'':`<button type="button" class="danger remove-line" data-remove-invoice-line="${index}" aria-label="Remove">×</button>`}</div>`).join('')||'<p class="empty">Search and add at least one product.</p>';renderInvoicePicker();renderInvoiceTotals()}
function addInvoiceProduct(productId){const product=state.inventory.find(item=>item.product_id===productId);if(!product||state.invoiceLines.some(line=>line.product_id===productId))return;state.invoiceLines.push({product_id:product.product_id,product_name:product.product_name,sku:product.sku,unit:product.unit,available_qty:Number(product.available_qty),quantity:1,unit_price_paise:Number(product.selling_price_paise||0),gst_bps:500});renderInvoiceLines()}
async function openInvoice(customerId='',order=null,existing=null){if(!state.inventory.length)await loadInventory();if(!state.customers.length)await loadCustomers();const form=$('#invoice-form');form.reset();state.editingInvoiceId=existing?.invoice?.id||null;state.invoiceOrderId=order?.id||null;const today=businessToday(),invoice=existing?.invoice||null,selectedCustomer=order?.customer_id||invoice?.customer_id||customerId;$('#invoice-date').value=invoice?.invoice_date||today;$('#invoice-customer').value=state.customers.some(c=>c.id===selectedCustomer)?selectedCustomer:'';const customer=state.customers.find(c=>c.id===$('#invoice-customer').value);$('#invoice-due-date').value=invoice?.due_date||datePlus($('#invoice-date').value,customer?.credit_days||0);form.elements.discount.value=((Number(invoice?.discount_paise||0))/100).toFixed(2);form.elements.paid.value=((Number(invoice?.paid_paise||0))/100).toFixed(2);form.elements.payment_method.value=invoice?.payment_method||'CREDIT';form.elements.notes.value=invoice?.notes||'';$('#invoice-product-search').value='';$('#invoice-product-search').disabled=!!order;$('#invoice-customer').disabled=!!order;$('#invoice-product-section').classList.toggle('checkout-locked',!!order);$('#invoice-order-note').hidden=!order;$('#invoice-order-note').textContent=order?`Processing ${order.order_number}. All picked items will be checked out together and stock will be deducted once.`:'';$('#invoice-dialog-kicker').textContent=order?'ORDER CHECKOUT':invoice?'EDIT SALE':'NEW SALE';$('#invoice-dialog-title').textContent=order?'Process picked order':invoice?`Edit ${invoice.invoice_number}`:'Create invoice';$('#invoice-dialog-copy').textContent=order?'Review the estimated invoice, then post it for dispatch.':invoice?.source_device!=='cloudflare-admin'?'Update the online copy only. The invoice on the Amul PC is not changed.':invoice?'Update customer, products, payment and totals.':'Complete the three short sections below.';$('#post-invoice').textContent=order?'Create invoice & mark processed':invoice?'Update invoice':'Post invoice & deduct stock';if(order){state.invoiceLines=(order.lines||[]).map(line=>{const product=state.inventory.find(item=>item.product_id===line.product_id)||{};return{product_id:line.product_id,product_name:line.product_name,sku:product.sku||line.product_id,unit:line.unit||product.unit||'PCS',available_qty:Number(line.quantity),quantity:Number(line.picked_qty||line.quantity),unit_price_paise:Number(line.price_paise||0),gst_bps:Number(line.gst_bps||0)}})}else if(existing){state.invoiceLines=(existing.lines||[]).map(line=>{const product=state.inventory.find(item=>item.product_id===line.product_id)||{};return{product_id:line.product_id,product_name:line.product_name,sku:line.sku||product.sku||line.product_id,unit:line.unit||product.unit||'PCS',available_qty:Number(product.available_qty||0)+Number(line.quantity),quantity:Number(line.quantity),unit_price_paise:Number(line.unit_price_paise||0),gst_bps:Number(line.gst_bps||0)}})}else state.invoiceLines=[];$('#invoice-error').textContent='';renderInvoiceLines();$('#invoice-dialog').showModal()}
async function editInvoice(id){const detail=await api(`/api/invoices/${encodeURIComponent(id)}`);await openInvoice(detail.invoice.customer_id,null,detail)}
function renderInvoiceDocument(data){const i=data.invoice,customer=state.customers.find(c=>c.id===i.customer_id)||{};return `<div class="invoice-doc-head"><div><h1>MR ENTERPRISES</h1><p>Amul Distribution</p><p class="meta">Tax invoice / sales invoice</p></div><div class="invoice-doc-meta"><strong>${escapeHtml(i.invoice_number)}</strong><p>Invoice: ${displayDate(i.invoice_date)}</p><p>Due: ${displayDate(i.due_date)}</p><p>Status: ${escapeHtml(i.status==='VOID'?'VOID':i.payment_status)}</p></div></div><div class="invoice-addresses"><div><small class="eyebrow">Bill to</small><h3>${escapeHtml(i.customer_name)}</h3><p>${escapeHtml(customer.address||'')}</p>${customer.gstin?`<p>GSTIN: ${escapeHtml(customer.gstin)}</p>`:''}<p>${escapeHtml(i.mobile||'')}</p></div><div><small class="eyebrow">Route / payment</small><p>${escapeHtml(i.route_name||'No route')}</p><p>${escapeHtml(i.payment_method||'')}</p></div></div>${data.lines.length?`<table><thead><tr><th>Item</th><th>Qty</th><th>Rate</th><th>GST</th><th>Amount</th></tr></thead><tbody>${data.lines.map(line=>`<tr><td>${escapeHtml(line.product_name)}<br><small>${escapeHtml(line.sku||'')}</small></td><td>${line.quantity} ${escapeHtml(line.unit)}</td><td>${money(line.unit_price_paise)}</td><td>${line.gst_bps==null?money(line.tax_paise)+' (tax)':(Number(line.gst_bps)/100).toFixed(2)+'%'}</td><td>${money(line.total_paise)}</td></tr>`).join('')}</tbody></table>`:'<p class="empty">Line details are retained on the source PC for this synced invoice.</p>'}<div class="invoice-doc-totals"><div><span>Subtotal</span><strong>${money(i.subtotal_paise||i.total_paise)}</strong></div><div><span>GST</span><strong>${money(i.tax_paise)}</strong></div><div><span>Discount</span><strong>− ${money(i.discount_paise)}</strong></div><div class="grand-total"><span>Total</span><strong>${money(i.total_paise)}</strong></div><div><span>Received</span><strong>${money(i.paid_paise)}</strong></div><div><span>Balance due</span><strong>${money(i.outstanding_paise)}</strong></div></div>${i.notes?`<p><strong>Note:</strong> ${escapeHtml(i.notes)}</p>`:''}<p class="meta">Computer-generated invoice from FrostFlow Online.</p>`}
async function viewInvoice(id){const data=await api(`/api/invoices/${encodeURIComponent(id)}`);state.currentInvoice=data;$('#invoice-print').innerHTML=renderInvoiceDocument(data);$('#invoice-view-dialog').showModal()}

function whatsappPageUrl({templateName='',customerName='',phone='',parameters=[]}={}){const url=new URL('/whatsapp/',location.origin);if(templateName)url.searchParams.set('template',templateName);if(customerName)url.searchParams.set('name',customerName);if(phone)url.searchParams.set('phone',phone);if(parameters.length)url.searchParams.set('parameters',JSON.stringify(parameters));return url}
function openWhatsAppPage(options={}){location.assign(whatsappPageUrl(options))}
function openTemplateComposer(options={}){openWhatsAppPage(options);return Promise.resolve()}

function openCustomerEditor(customer=null){const form=$('#customer-form');form.reset();state.editingCustomerId=customer?.id||null;$('#customer-dialog-title').textContent=customer?'Edit customer':'Add customer';$('#save-customer').textContent=customer?'Update customer':'Save customer';form.elements.name.value=customer?.name||'';form.elements.whatsapp_number.value=customer?.whatsapp_number||customer?.mobile||'';form.elements.whatsapp_number.disabled=customer?.source==='WHATSAPP';form.elements.gstin.value=customer?.gstin||'';form.elements.route_name.innerHTML=customerRouteOptions(customer?.route_name||'');form.elements.route_name.value=customer?.route_name==='Unassigned route'?'':customer?.route_name||'';form.elements.city.value=customer?.city||'';form.elements.credit_days.value=Number(customer?.credit_days||0);form.elements.address.value=customer?.address||'';$('#customer-error').textContent=customer?.source==='WHATSAPP'?'The WhatsApp number is locked so the existing chat history stays intact.':'';$('#customer-dialog').showModal()}
async function openOrder(){if(!state.inventory.length)await loadInventory();if(!state.customers.length)await loadCustomers();renderCart();$('#order-dialog').showModal()}
document.querySelectorAll('nav button').forEach(button=>button.addEventListener('click',async()=>{document.querySelectorAll('nav button,.tab').forEach(node=>node.classList.remove('active'));button.classList.add('active');$('#'+button.dataset.tab).classList.add('active');try{if(button.dataset.tab==='dashboard')await Promise.all([loadDashboard(),loadReconciliation()]);if(button.dataset.tab==='catalog')await loadInventory();if(button.dataset.tab==='orders')await loadOrders();if(button.dataset.tab==='customers')await loadCustomers();if(button.dataset.tab==='accounts')await loadAccounts()}catch(error){toast(error.message)}}));
document.querySelectorAll('[data-quick-action]').forEach(button=>button.addEventListener('click',()=>{const action=button.dataset.quickAction;if(action==='order')openOrder().catch(error=>toast(error.message));if(action==='invoice')openInvoice().catch(error=>toast(error.message));if(action==='customer')$('#new-customer').click();if(action==='message')openWhatsAppPage()}));
$('#inventory-list').addEventListener('click',async event=>{const setStock=event.target.closest('[data-set-stock]');if(setStock){const product=findProduct(setStock.dataset.setStock),form=$('#stock-form');form.reset();form.elements.product_id.value=product.product_id;form.elements.stock_qty.value=product.stock_qty;form.elements.unit.value=[...form.elements.unit.options].some(option=>option.value===product.unit)?product.unit:'BX';$('#stock-product').textContent=`${product.product_name} · ${product.sku||product.product_id} · ${product.reserved_qty} reserved`;$('#stock-error').textContent='';$('#stock-dialog').showModal();return}const stockButton=event.target.closest('[data-stock-toggle]');if(stockButton){stockButton.disabled=true;try{await api(`/api/inventory/${encodeURIComponent(stockButton.dataset.stockToggle)}/availability`,{method:'PATCH',body:JSON.stringify({out_of_stock:stockButton.dataset.next==='out'})});await Promise.all([loadInventory(),loadDashboard()]);toast(stockButton.dataset.next==='out'?'Hidden from customer catalogue':'Product is available to customers')}catch(error){toast(error.message)}return}const topup=event.target.closest('[data-topup]');if(topup){const product=findProduct(topup.dataset.topup),form=$('#topup-form');form.reset();form.elements.product_id.value=product.product_id;$('#topup-product').textContent=`${product.product_name} · ${product.sku||product.product_id}`;$('#topup-dialog').showModal();return}const stepper=event.target.closest('.stepper');if(!stepper)return;if(event.target.matches('[data-plus]'))changeQuantity(stepper.dataset.product,1);if(event.target.matches('[data-minus]'))changeQuantity(stepper.dataset.product,-1)});
$('#cart-lines').addEventListener('click',event=>{const stepper=event.target.closest('.stepper');if(!stepper)return;if(event.target.matches('[data-plus]'))changeQuantity(stepper.dataset.product,1);if(event.target.matches('[data-minus]'))changeQuantity(stepper.dataset.product,-1)});
$('#search').addEventListener('input',renderInventory);$('#category').addEventListener('change',renderInventory);$('#refresh').addEventListener('click',loadInventory);$('#open-cart').addEventListener('click',openOrder);$('#new-order').addEventListener('click',openOrder);$('#order-search').addEventListener('input',renderOrders);$('#refresh-orders').addEventListener('click',()=>loadOrders().catch(error=>toast(error.message)));$('#refresh-all').addEventListener('click',async()=>{await Promise.all([loadDashboard(),loadReconciliation()]);toast('Online data refreshed')});
$('#quick-order').addEventListener('click',()=>openOrder().catch(error=>toast(error.message)));$('#quick-invoice').addEventListener('click',()=>openInvoice().catch(error=>toast(error.message)));$('#create-invoice').addEventListener('click',()=>openInvoice().catch(error=>toast(error.message)));$('#new-customer').addEventListener('click',()=>openCustomerEditor());
$('#customer-search').addEventListener('input',renderCustomerRoutes);let accountTimer;$('#account-search').addEventListener('input',()=>{clearTimeout(accountTimer);accountTimer=setTimeout(()=>loadAccounts().catch(error=>toast(error.message)),250)});
$('#customer-routes').addEventListener('click',event=>{const button=event.target.closest('[data-customer-route]');if(!button)return;state.selectedRoute=button.dataset.customerRoute;renderCustomerRoutes()});
$('#manage-routes').addEventListener('click',()=>{renderRouteManager();$('#route-error').textContent='';$('#route-dialog').showModal()});$('#close-route-dialog').addEventListener('click',()=>$('#route-dialog').close());
$('#route-form').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget,error=$('#route-error');error.textContent='';try{const route=await api('/api/routes',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(form)))});form.reset();await loadCustomers();renderRouteManager();toast(`${route.name} added`)}catch(problem){error.textContent=problem.message}});
$('#route-manager-list').addEventListener('click',async event=>{const button=event.target.closest('[data-save-route]');if(!button)return;const row=button.closest('.route-manager-row'),name=row.querySelector('input').value.trim(),oldName=button.dataset.saveRoute;$('#route-error').textContent='';button.disabled=true;try{await api('/api/routes',{method:'PUT',body:JSON.stringify({old_name:oldName,name})});if(state.selectedRoute===oldName)state.selectedRoute=name;await loadCustomers();renderRouteManager();toast(`Route renamed to ${name}`)}catch(error){$('#route-error').textContent=error.message;button.disabled=false}});
$('#customers-list').addEventListener('click',async event=>{const remove=event.target.closest('[data-delete-customer]');if(remove){if(!confirm(`Delete ${remove.dataset.deleteCustomerName}? Orders, invoices and WhatsApp history will remain intact.`))return;remove.disabled=true;try{await api(`/api/customers/${encodeURIComponent(remove.dataset.deleteCustomer)}`,{method:'DELETE'});await Promise.all([loadCustomers(),loadDashboard()]);toast(`${remove.dataset.deleteCustomerName} deleted`)}catch(error){toast(error.message);remove.disabled=false}return}const edit=event.target.closest('[data-edit-customer]');if(edit){const customer=state.customers.find(item=>item.id===edit.dataset.editCustomer);if(customer)openCustomerEditor(customer);return}const invoice=event.target.closest('[data-customer-invoice]');if(invoice){openInvoice(invoice.dataset.customerInvoice).catch(error=>toast(error.message));return}const chat=event.target.closest('[data-chat-phone]');if(chat){openWhatsAppPage({phone:chat.dataset.chatPhone});return}const button=event.target.closest('[data-invite-phone]');if(!button)return;openTemplateComposer({customerName:button.dataset.inviteName||'',phone:button.dataset.invitePhone||''}).catch(error=>toast(error.message))});
$('#invoices-list').addEventListener('click',async event=>{const view=event.target.closest('[data-view-invoice]');if(view){try{await viewInvoice(view.dataset.viewInvoice)}catch(error){toast(error.message)}return}const edit=event.target.closest('[data-edit-invoice]');if(edit){try{await editInvoice(edit.dataset.editInvoice)}catch(error){toast(error.message)}return}const remove=event.target.closest('[data-delete-invoice]');if(remove){const synced=remove.dataset.deleteInvoiceSource==='synced',paid=Number(remove.dataset.deleteInvoicePaid||0)>0,fromOrder=remove.dataset.deleteInvoiceOrder==='yes';let message=synced?'Remove this invoice from FrostFlow Online? The invoice on the Amul PC will not be changed.':fromOrder?'Delete this invoice? The order and stock will be reopened only if dispatch has not started.':'Delete this invoice and restore its stock?';if(paid&&!synced)message+=' Its linked online payment entry will also be removed.';if(!confirm(message))return;remove.disabled=true;try{const result=await api(`/api/invoices/${encodeURIComponent(remove.dataset.deleteInvoice)}`,{method:'DELETE'});await Promise.all([loadAccounts(),loadInventory(),loadDashboard(),loadCustomers(),loadOrders()]);toast(result.reopened_order_id?'Invoice deleted, stock restored and order reopened':result.stock_restored?'Invoice deleted and stock restored':result.order_preserved?'Invoice deleted; dispatched order and stock preserved':'Invoice removed from online view')}catch(error){toast(error.message);remove.disabled=false}return}const voidButton=event.target.closest('[data-void-invoice]');if(voidButton){if(!confirm('Void this invoice and restore its stock?'))return;voidButton.disabled=true;try{await api(`/api/invoices/${encodeURIComponent(voidButton.dataset.voidInvoice)}/void`,{method:'POST'});await Promise.all([loadAccounts(),loadInventory(),loadDashboard(),loadCustomers()]);toast('Invoice voided and stock restored')}catch(error){toast(error.message)}return}const button=event.target.closest('[data-payment-phone]');if(!button)return;openTemplateComposer({templateName:'payment_remainder',customerName:button.dataset.paymentName||'',phone:button.dataset.paymentPhone||'',parameters:[button.dataset.paymentName,button.dataset.paymentInvoice,button.dataset.paymentAmount,button.dataset.paymentDue]}).catch(error=>toast(error.message))});
$('#order-customer').addEventListener('change',event=>{const customer=state.customers.find(c=>c.id===event.target.value),form=$('#order-form');if(!customer)return;form.elements.customer_name.value=customer.name;form.elements.phone.value=customer.whatsapp_number||customer.mobile||'';form.elements.route_name.value=customer.route_name||''});
$('#add-custom-product').addEventListener('click',()=>{const name=$('#custom-product-name').value.trim(),quantity=Number($('#custom-product-quantity').value),unit=$('#custom-product-unit').value,price=Number($('#custom-product-price').value),error=$('#custom-product-error');error.textContent='';if(!name){error.textContent='Enter a product name.';return}if(!Number.isFinite(quantity)||quantity<=0||quantity>1000){error.textContent='Enter a quantity from 0.01 to 1000.';return}if(!Number.isFinite(price)||price<0||price>10000000){error.textContent='Enter a valid unit price.';return}const productId=`custom:${crypto.randomUUID()}`,product={product_id:productId,product_name:name,unit,selling_price_paise:Math.round(price*100),available_qty:1000,is_custom:true};state.customProducts.set(productId,product);state.cart.set(productId,quantity);$('#custom-product-name').value='';$('#custom-product-quantity').value='1';$('#custom-product-price').value='0';renderCart();toast(`${name} added to this order`)});
$('#order-form').addEventListener('submit',async event=>{event.preventDefault();$('#order-error').textContent='';const data=new FormData(event.currentTarget),lines=[...state.cart].map(([product_id,quantity])=>{const product=findProduct(product_id);return product?.is_custom?{custom:true,product_name:product.product_name,quantity,unit:product.unit,unit_price_paise:product.selling_price_paise}:{product_id,quantity,unit:product?.unit||'PCS'}});try{const result=await api('/api/orders',{method:'POST',body:JSON.stringify({request_id:crypto.randomUUID(),customer_id:data.get('customer_id'),customer_name:data.get('customer_name'),phone:data.get('phone'),route_name:data.get('route_name'),delivery_date:data.get('delivery_date'),note:data.get('note'),lines})});state.cart.clear();state.customProducts.clear();event.currentTarget.reset();$('#order-dialog').close();await Promise.all([loadInventory(),loadOrders(),loadDashboard()]);toast(`Order ${result.order_number} saved`)}catch(error){$('#order-error').textContent=error.message}});
$('#topup-form').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget,data=new FormData(form);$('#topup-error').textContent='';try{await api('/api/purchase-topups',{method:'POST',body:JSON.stringify({product_id:data.get('product_id'),quantity:data.get('quantity'),reference:data.get('reference'),note:data.get('note')})});$('#topup-dialog').close();await loadInventory();toast('Latest purchase top-up saved')}catch(error){$('#topup-error').textContent=error.message}});
$('#stock-form').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget,data=new FormData(form);$('#stock-error').textContent='';try{await api(`/api/inventory/${encodeURIComponent(data.get('product_id'))}/quantity`,{method:'PATCH',body:JSON.stringify({stock_qty:data.get('stock_qty'),unit:data.get('unit'),note:data.get('note')})});$('#stock-dialog').close();await Promise.all([loadInventory(),loadDashboard()]);toast('Current stock updated')}catch(error){$('#stock-error').textContent=error.message}});
$('#customer-form').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget,data=Object.fromEntries(new FormData(form)),id=state.editingCustomerId;$('#customer-error').textContent='';try{const customer=await api(id?`/api/customers/${encodeURIComponent(id)}`:'/api/customers',{method:id?'PUT':'POST',body:JSON.stringify(data)});$('#customer-dialog').close();state.editingCustomerId=null;await loadCustomers();toast(`${customer.name} ${id?'updated':'saved'}`)}catch(error){$('#customer-error').textContent=error.message}});
$('#invoice-customer').addEventListener('change',event=>{const customer=state.customers.find(c=>c.id===event.target.value),date=$('#invoice-date').value||businessToday();$('#invoice-due-date').value=datePlus(date,customer?.credit_days||0);renderInvoiceTotals()});
$('#invoice-date').addEventListener('change',()=>{const customer=state.customers.find(c=>c.id===$('#invoice-customer').value);$('#invoice-due-date').value=datePlus($('#invoice-date').value,customer?.credit_days||0)});
$('#invoice-product-search').addEventListener('input',renderInvoicePicker);
$('#invoice-product-results').addEventListener('click',event=>{const button=event.target.closest('[data-invoice-product]');if(button)addInvoiceProduct(button.dataset.invoiceProduct)});
$('#invoice-lines').addEventListener('input',event=>{const row=event.target.closest('[data-invoice-line]');if(!row)return;const line=state.invoiceLines[Number(row.dataset.invoiceLine)];if(event.target.dataset.lineField==='quantity')line.quantity=Math.max(.01,Math.min(line.available_qty,Number(event.target.value)||0));if(event.target.dataset.lineField==='price')line.unit_price_paise=Math.max(0,Math.round((Number(event.target.value)||0)*100));if(event.target.dataset.lineField==='gst')line.gst_bps=Math.max(0,Math.min(5000,Math.round((Number(event.target.value)||0)*100)));renderInvoiceTotals();row.querySelector('.invoice-line-total').textContent=money(Math.round(line.quantity*line.unit_price_paise*(1+line.gst_bps/10000)))});
$('#invoice-lines').addEventListener('click',event=>{const button=event.target.closest('[data-remove-invoice-line]');if(!button)return;state.invoiceLines.splice(Number(button.dataset.removeInvoiceLine),1);renderInvoiceLines()});
$('#invoice-discount').addEventListener('input',renderInvoiceTotals);
$('#invoice-paid').addEventListener('input',event=>{const method=$('#invoice-form').elements.payment_method;if(Number(event.target.value)>0&&method.value==='CREDIT')method.value='CASH';if(Number(event.target.value)<=0)method.value='CREDIT'});
$('#invoice-form').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget,data=new FormData(form),button=$('#post-invoice'),totals=invoiceTotals(),editingId=state.editingInvoiceId,orderId=state.invoiceOrderId;$('#invoice-error').textContent='';button.disabled=true;try{const payload={request_id:crypto.randomUUID(),order_id:orderId,customer_id:form.elements.customer_id.value,invoice_date:data.get('invoice_date'),due_date:data.get('due_date'),discount_paise:Math.round(Number(data.get('discount')||0)*100),paid_paise:Math.round(Number(data.get('paid')||0)*100),payment_method:data.get('payment_method'),notes:data.get('notes'),lines:state.invoiceLines.map(line=>({product_id:line.product_id,quantity:line.quantity,unit_price_paise:line.unit_price_paise,gst_bps:line.gst_bps}))};const result=await api(editingId?`/api/invoices/${encodeURIComponent(editingId)}`:'/api/invoices',{method:editingId?'PUT':'POST',body:JSON.stringify(payload)});$('#invoice-dialog').close();state.invoiceLines=[];state.editingInvoiceId=null;state.invoiceOrderId=null;$('#invoice-customer').disabled=false;$('#invoice-product-search').disabled=false;document.querySelector('[data-tab="accounts"]').click();await Promise.all([loadAccounts(),loadInventory(),loadDashboard(),loadCustomers(),loadOrders()]);toast(`Invoice ${result.invoice_number} ${editingId?'updated':'posted'} · ${money(totals.total)}`);await viewInvoice(result.id)}catch(error){$('#invoice-error').textContent=error.message;renderInvoiceTotals()}});
$('#print-invoice').addEventListener('click',()=>window.print());$('#close-invoice-view').addEventListener('click',()=>$('#invoice-view-dialog').close());
function sendDeliveryUpdate(button){return openTemplateComposer({templateName:'order_delivery_update',customerName:button.dataset.deliveryName||'',phone:button.dataset.deliveryPhone||'',parameters:[button.dataset.deliveryName,button.dataset.deliveryOrder,button.dataset.deliveryStatus,button.dataset.deliveryDate]})}
$('#orders-list').addEventListener('click',async event=>{const delivery=event.target.closest('[data-delivery-phone]');if(delivery){sendDeliveryUpdate(delivery).catch(error=>toast(error.message));return}const pick=event.target.closest('[data-pick-plus],[data-pick-minus]');if(pick){const stepper=pick.closest('[data-pick-order]'),current=Number(stepper.dataset.picked),ordered=Number(stepper.dataset.ordered),step=Number(stepper.dataset.pickStep||1),next=Math.max(0,Math.min(ordered,current+(pick.matches('[data-pick-plus]')?step:-step)));pick.disabled=true;try{await api(`/api/orders/${encodeURIComponent(stepper.dataset.pickOrder)}/pick`,{method:'PATCH',body:JSON.stringify({line_no:Number(stepper.dataset.pickLine),picked_qty:next})});await loadOrders()}catch(error){toast(error.message)}return}const checkout=event.target.closest('[data-checkout-order]');if(checkout){const order=state.orders.find(item=>item.id===checkout.dataset.checkoutOrder);if(order)openInvoice(order.customer_id,order).catch(error=>toast(error.message));return}const button=event.target.closest('[data-order-action]');if(!button)return;button.disabled=true;try{const result=await api(`/api/orders/${encodeURIComponent(button.dataset.id)}/${button.dataset.orderAction}`,{method:'POST'});await Promise.all([loadOrders(),loadDashboard()]);if(result.notification?.sent)toast(`${result.notification.status} · customer notified`);else if(result.notification?.error)toast(`Order updated, but WhatsApp failed: ${result.notification.error}`);else toast('Order updated')}catch(error){toast(error.message)}finally{button.disabled=false}});
$('#orders-list').addEventListener('submit',async event=>{const form=event.target.closest('[data-crate-order]');if(!form)return;event.preventDefault();const button=form.querySelector('button'),data=new FormData(form);button.disabled=true;try{await api(`/api/orders/${encodeURIComponent(form.dataset.crateOrder)}/crate`,{method:'POST',body:JSON.stringify({crate_code:data.get('crate_code')})});await loadOrders();toast('Complete order added to crate')}catch(error){toast(error.message)}finally{button.disabled=false}});
$('#distribution-orders-list').addEventListener('click',event=>{const button=event.target.closest('[data-delivery-phone]');if(button)sendDeliveryUpdate(button).catch(error=>toast(error.message))});
if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});
const requestedTab=new URLSearchParams(location.search).get('open');if(['orders','customers','accounts','catalog'].includes(requestedTab))document.querySelector(`[data-tab="${requestedTab}"]`)?.click();
Promise.all([loadDashboard(),loadReconciliation(),loadInventory(),loadCustomers()]).catch(error=>toast(error.message));
